"""Uber One cancellation loop for the week 10 "Persuasive Design" slide.

Cuts the four phone screens out of FTC v. Uber, Ex. 20 (ftc-uber-ex20.jpg, the complaint's embedded JPEG, unmodified) and redraws the exhibit's red arrows in CTA wayfinding style: a blue arrow knocked out of a white disc on a blue tile, as on the station signs, with the loop back to the first screen drawn as one gently arched route line. Writes a transparent uber-one-cancellation-loop.png beside this script.

    uv run --with pillow python docs/assets/uber-cancel-loop/make_figure.py
"""
from pathlib import Path

from PIL import Image, ImageDraw

HERE = Path(__file__).resolve().parent

SCALE = 2  # output pixels per exhibit pixel, so the drawn arrows stay crisp
BLUE = "#005daa"  # $cta-blue-dark in docs/slides/theme/blue-line.scss
WHITE = "#ffffff"

# Screen boxes in the exhibit's own pixels (left, top, right, bottom), measured from ftc-uber-ex20.jpg.
SCREENS = [(0, 8, 248, 614), (297, 8, 547, 614), (593, 8, 837, 616), (884, 0, 1134, 614)]

GAP = 120  # between screens, room for an arrow tile
TILE = 84  # arrow tile size
LOOP_DROP = 70  # from the bottom of the screens to the lowest point of the loop's arch
LINE_W = 16  # loop route stroke
SUPERSAMPLE = 4  # the arch is drawn this much larger, then scaled down, so its edges are smooth
MARGIN = 24


def arrow_tile(draw, cx, cy, direction):
    """A CTA sign arrow: blue tile, white disc, blue open-chevron arrow pointing left or right."""
    s = SCALE
    half = TILE * s / 2
    draw.rounded_rectangle([cx - half, cy - half, cx + half, cy + half], radius=10 * s, fill=BLUE)
    r = half * 0.78
    draw.ellipse([cx - r, cy - r, cx + r, cy + r], fill=WHITE)
    sign = 1 if direction == "right" else -1
    tip = (cx + sign * r * 0.62, cy)
    tail = (cx - sign * r * 0.62, cy)
    w = round(r * 0.2)
    draw.line([tail, tip], fill=BLUE, width=w)
    arm = r * 0.5
    for dy in (-1, 1):
        draw.line([(tip[0] - sign * arm, cy + dy * arm), tip], fill=BLUE, width=w, joint="curve")
    draw.ellipse([tip[0] - w / 2, cy - w / 2, tip[0] + w / 2, cy + w / 2], fill=BLUE)


def main():
    src = Image.open(HERE / "ftc-uber-ex20.jpg").convert("RGB")
    s = SCALE
    crops = [src.crop(box) for box in SCREENS]
    width = sum(c.width for c in crops) + GAP * (len(crops) - 1) + 2 * MARGIN
    screen_h = max(c.height for c in crops)
    height = MARGIN + screen_h + 16 + LOOP_DROP + TILE // 2 + MARGIN
    out = Image.new("RGBA", (width * s, height * s), (0, 0, 0, 0))
    draw = ImageDraw.Draw(out)

    x = MARGIN
    centers = []
    for i, crop in enumerate(crops):
        out.paste(crop.resize((crop.width * s, crop.height * s), Image.LANCZOS), (x * s, MARGIN * s))
        centers.append(x + crop.width / 2)
        if i < len(crops) - 1:
            arrow_tile(draw, (x + crop.width + GAP / 2) * s, (MARGIN + screen_h / 2) * s, "right")
        x += crop.width + GAP

    # The loop: one arched line from under the last screen back to under the first, a quadratic curve sagging LOOP_DROP at its middle.
    k = s * SUPERSAMPLE
    top = MARGIN + screen_h + 16
    left, right = centers[0], centers[-1]
    mid = (left + right) / 2
    pts = []
    for i in range(201):
        u = i / 200
        px = (1 - u) ** 2 * right + 2 * u * (1 - u) * mid + u**2 * left
        py = top + 2 * u * (1 - u) * 2 * LOOP_DROP
        pts.append((px * k, py * k))
    layer = Image.new("RGBA", (width * k, height * k), (0, 0, 0, 0))
    ldraw = ImageDraw.Draw(layer)
    w = LINE_W * k
    # Filled as one outline polygon, since a wide multi-segment line leaves seams at every joint.
    upper, lower = [], []
    for i, (px, py) in enumerate(pts):
        (ax, ay), (bx, by) = pts[max(i - 1, 0)], pts[min(i + 1, len(pts) - 1)]
        dx, dy = bx - ax, by - ay
        norm = (dx * dx + dy * dy) ** 0.5
        nx, ny = -dy / norm * w / 2, dx / norm * w / 2
        upper.append((px + nx, py + ny))
        lower.append((px - nx, py - ny))
    ldraw.polygon(upper + lower[::-1], fill=BLUE)
    for cx, cy in (pts[0], pts[-1]):
        ldraw.ellipse([cx - w / 2, cy - w / 2, cx + w / 2, cy + w / 2], fill=BLUE)
    out.alpha_composite(layer.resize(out.size, Image.LANCZOS))
    draw = ImageDraw.Draw(out)
    arrow_tile(draw, mid * s, (top + LOOP_DROP) * s, "left")

    out.save(HERE / "uber-one-cancellation-loop.png", optimize=True)


if __name__ == "__main__":
    main()
